from collections import deque
def f(I):
    H,W=len(I),len(I[0])
    seen=[[False]*W for _ in range(H)]; comps=[]
    for i in range(H):
        for j in range(W):
            if not seen[i][j] and I[i][j]==0:
                q=deque([(i,j)]); seen[i][j]=True; comp=[(i,j)]
                while q:
                    a,b=q.popleft()
                    for di,dj in((1,0),(-1,0),(0,1),(0,-1)):
                        ni,nj=a+di,b+dj
                        if 0<=ni<H and 0<=nj<W and not seen[ni][nj] and I[ni][nj]==0:
                            seen[ni][nj]=True; comp.append((ni,nj)); q.append((ni,nj))
                comps.append(comp)
    O=[row[:] for row in I]
    for c in comps:
        has_gap=any(((a>0 and I[a-1][b]==1 and a<H-1 and I[a+1][b]==1) or
                     (b>0 and I[a][b-1]==1 and b<W-1 and I[a][b+1]==1)) for a,b in c)
        if has_gap: continue
        # dist-1 cells get recolored; others untouched
        rec={(a,b) for a,b in c if min(max(abs(a-x),abs(b-y)) for x,y in [(x,y) for x in range(H) for y in range(W) if I[x][y]==1])==1}
        # BFS exterior from border over cells not recolored
        ext=set(c) - rec
        bq=deque()
        for a,b in c:
            if (a,b) in ext and (a in(0,H-1) or b in(0,W-1)): bq.append((a,b))
        while bq:
            a,b=bq.popleft()
            for di,dj in((1,0),(-1,0),(0,1),(0,-1)):
                ni,nj=a+di,b+dj
                if (ni,nj) in c and (ni,nj) in ext: ext.add((ni,nj)); bq.append((ni,nj))
        for a,b in rec:
            O[a][b]= 3 if (a,b) not in ext else 2
    return O
