    # 1 = wall. Flood fill from border over 0s; unreached interior 0s -> 3. Border-reachable 0s stay 0 (background).
    lab=[[None]*W for _ in range(H)]; q=deque()
    for r in range(H):
        for c in range(W):
            if inp[r][c]==0 and not(r in(0,H-1) or c in(0,W-1)):
                pass
    # unreached interior zeros -> 3, reachable interior 0s -> 2, background 0s stay 0, walls keep 1
    res=[row[:] for row in inp]
    seen=set()
    qq=deque()
    for r in range(H):
        for c in (0,W-1):
            if inp[r][c]==0: qq.append((r,c)); seen.add((r,c))
    for c in range(W):
        for r in (0,H-1):
            if inp[r][c]==0 and (r,c) not in seen: qq.append((r,c)); seen.add((r,c))
